# Disbursement Roll Migration Test Script (PowerShell)\nWrite-Host \"🚀 Disbursement Roll Migration Tester\" -ForegroundColor Green\nWrite-Host \"====================================\" -ForegroundColor Green\n\n# Configuration\n$baseUrl = \"http://localhost:5000/api/v1\"\n\n# Step 1: Test server health\nWrite-Host \"`n1️⃣ Testing server health...\" -ForegroundColor Yellow\ntry {\n    $healthResponse = Invoke-RestMethod -Uri \"$baseUrl/health\" -Method Get\n    Write-Host \"✅ Server is healthy!\" -ForegroundColor Green\n    Write-Host \"Response: $($healthResponse | ConvertTo-Json)\" -ForegroundColor Cyan\n} catch {\n    Write-Host \"❌ Server is not responding\" -ForegroundColor Red\n    Write-Host \"Make sure the server is running on port 5000\" -ForegroundColor Red\n    exit 1\n}\n\n# Step 2: Get login credentials\nWrite-Host \"`n2️⃣ Please provide login credentials:\" -ForegroundColor Yellow\n$email = Read-Host \"📧 Email\"\n$password = Read-Host \"🔑 Password\" -AsSecureString\n$passwordPlain = [Runtime.InteropServices.Marshal]::PtrToStringAuto([Runtime.InteropServices.Marshal]::SecureStringToBSTR($password))\n\n# Step 3: Login to get token\nWrite-Host \"`n3️⃣ Logging in...\" -ForegroundColor Yellow\ntry {\n    $loginBody = @{\n        email = $email\n        password = $passwordPlain\n    } | ConvertTo-Json\n    \n    $loginResponse = Invoke-RestMethod -Uri \"$baseUrl/auth/login\" -Method Post -Body $loginBody -ContentType \"application/json\"\n    \n    if ($loginResponse.success) {\n        $token = $loginResponse.data.token\n        Write-Host \"✅ Login successful!\" -ForegroundColor Green\n    } else {\n        Write-Host \"❌ Login failed: $($loginResponse.message)\" -ForegroundColor Red\n        exit 1\n    }\n} catch {\n    Write-Host \"❌ Login failed: $($_.Exception.Message)\" -ForegroundColor Red\n    exit 1\n}\n\n# Step 4: Get branch ID (optional)\nWrite-Host \"`n4️⃣ Branch Information:\" -ForegroundColor Yellow\n$branchId = Read-Host \"🏢 Branch ID (optional, press Enter to skip)\"\n\n# Create headers with token\n$headers = @{\n    \"Authorization\" = \"Bearer $token\"\n    \"Content-Type\" = \"application/json\"\n}\n\n# Step 5: Get current disbursement roll\nWrite-Host \"`n5️⃣ Getting current disbursement roll...\" -ForegroundColor Yellow\ntry {\n    $query = if ($branchId) { \"?branchId=$branchId\" } else { \"\" }\n    $currentRoll = Invoke-RestMethod -Uri \"$baseUrl/disbursement-roll$query\" -Method Get -Headers $headers\n    Write-Host \"📄 Current Roll:\" -ForegroundColor Cyan\n    Write-Host ($currentRoll | ConvertTo-Json -Depth 5) -ForegroundColor White\n} catch {\n    Write-Host \"⚠️ Could not get current roll: $($_.Exception.Message)\" -ForegroundColor Orange\n}\n\n# Step 6: Run migration\nWrite-Host \"`n6️⃣ Running migration...\" -ForegroundColor Yellow\ntry {\n    $migrationResponse = Invoke-RestMethod -Uri \"$baseUrl/disbursement-roll/migrate\" -Method Post -Headers $headers -Body \"{}\"\n    \n    if ($migrationResponse.success) {\n        Write-Host \"✅ Migration completed successfully!\" -ForegroundColor Green\n        Write-Host \"📈 Updated $($migrationResponse.data.updatedRecords) out of $($migrationResponse.data.totalRecords) records\" -ForegroundColor Green\n    } else {\n        Write-Host \"❌ Migration failed: $($migrationResponse.message)\" -ForegroundColor Red\n    }\n    \n    Write-Host \"📄 Migration Response:\" -ForegroundColor Cyan\n    Write-Host ($migrationResponse | ConvertTo-Json -Depth 5) -ForegroundColor White\n} catch {\n    Write-Host \"❌ Migration failed: $($_.Exception.Message)\" -ForegroundColor Red\n    Write-Host \"Response: $($_.ErrorDetails.Message)\" -ForegroundColor Red\n}\n\n# Step 7: Get updated disbursement roll\nWrite-Host \"`n7️⃣ Getting disbursement roll after migration...\" -ForegroundColor Yellow\ntry {\n    $updatedRoll = Invoke-RestMethod -Uri \"$baseUrl/disbursement-roll$query\" -Method Get -Headers $headers\n    Write-Host \"📄 Updated Roll:\" -ForegroundColor Cyan\n    Write-Host ($updatedRoll | ConvertTo-Json -Depth 5) -ForegroundColor White\n} catch {\n    Write-Host \"⚠️ Could not get updated roll: $($_.Exception.Message)\" -ForegroundColor Orange\n}\n\n# Step 8: Show comparison\nif ($currentRoll -and $updatedRoll) {\n    Write-Host \"`n📊 COMPARISON:\" -ForegroundColor Magenta\n    \n    Write-Host \"Before Migration:\" -ForegroundColor Yellow\n    if ($currentRoll.success) {\n        $before = $currentRoll.data.disbursementRoll\n        Write-Host \"  - disbursementRoll: $($before.disbursementRoll)\" -ForegroundColor White\n        Write-Host \"  - disNo: $($before.disNo)\" -ForegroundColor White\n        Write-Host \"  - dailyDisNo: $($before.dailyDisNo)\" -ForegroundColor White\n        Write-Host \"  - currentDisbursementNo: $($before.currentDisbursementNo)\" -ForegroundColor White\n        Write-Host \"  - cumulativeDisNo: $($before.cumulativeDisNo)\" -ForegroundColor White\n    }\n    \n    Write-Host \"`nAfter Migration:\" -ForegroundColor Yellow\n    if ($updatedRoll.success) {\n        $after = $updatedRoll.data.disbursementRoll\n        Write-Host \"  - disbursementRoll: $($after.disbursementRoll)\" -ForegroundColor White\n        Write-Host \"  - disNo: $($after.disNo)\" -ForegroundColor White\n        Write-Host \"  - dailyDisNo: $($after.dailyDisNo)\" -ForegroundColor White\n        Write-Host \"  - currentDisbursementNo: $($after.currentDisbursementNo)\" -ForegroundColor White\n        Write-Host \"  - cumulativeDisNo: $($after.cumulativeDisNo)\" -ForegroundColor White\n    }\n}\n\nWrite-Host \"`n🎉 Test completed!\" -ForegroundColor Green